<script setup>import {ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';const material=ref('MAT-001'),msg=ref('');const create=()=>{const r=actions.createInventory('',material.value);msg.value=r.ok?'已创建盘点计划':'操作失败'}</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">资</div><div><h2>物资管理</h2><p>查看台账、创建盘点并复核结果</p></div></div><article class="panel"><div class="button-row"><select v-model="material"><option v-for="m in state.materials" :key="m.id" :value="m.id">{{m.name}} · {{m.station}}</option></select><button class="primary-button active" @click="create">创建盘点计划</button></div></article><p v-if="msg" class="action-message">{{msg}}</p><div class="table-card"><table><thead><tr><th>物资</th><th>站点</th><th>数量</th><th>状态</th></tr></thead><tbody><tr v-for="m in state.materials" :key="m.id"><td>{{m.name}}</td><td>{{m.station}}</td><td>{{m.quantity}}</td><td>{{m.status}}</td></tr></tbody></table></div><article class="panel"><h3>盘点计划</h3><div v-for="p in state.inventoryPlans" :key="p.id" class="alert-row"><span>{{p.id}} · {{p.station}} · {{p.status}} · 差异 {{p.difference??'—'}}</span><button v-if="p.status==='待复核'" class="secondary-button" @click="actions.reviewInventory(p.id)">管理员复核</button></div></article></section></template>
